WITH filtered_employees AS (SELECT * FROM employees WHERE LENGTH(email) >= 14), salary_bucket_summary AS (SELECT CASE WHEN salary >= 157000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END AS salary_bucket, job_title, AVG(salary) AS avg_salary FROM filtered_employees GROUP BY CASE WHEN salary >= 157000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END, job_title) SELECT salary_bucket, avg_salary FROM salary_bucket_summary WHERE avg_salary > 131000 ORDER BY avg_salary, salary_bucket
